import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.hibernate.annotations.Fetch;
import org.hibernate.annotations.FetchMode;
import org.hibernate.annotations.Generated;

/** A claim a person makes: an amount (two decimals), a date, a note and a status. A claim with a
 *  negative amount is a correction of a settled claim of the same person, named by its number. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number on its sheet, given when it is opened and kept when voided; null for a
     *  claim never opened. */
    @Column(name = "number")
    private String number;

    /** The due fixed when the claim was settled; null when not settled, or settled with no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Who opened the claim; null for a claim never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Whether the person's last statement bound this claim to the due it had then. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due the last statement bound the claim to; null when unbound, or bound with no rate
     *  (its due then stays live). */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** Whether the last statement bound the claim to n/a: it had no due then because the rate that
     *  would apply to it had ended (its due then does not stay live). */
    @Column(name = "stated_na", nullable = false)
    private boolean statedNa;

    /** The number of the settled claim of the same person this correction corrects; null for a claim
     *  that is not a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The date of the claim this correction corrects, which it rounds by; null for a claim that is
     *  not a correction. */
    @Column(name = "corrected_date")
    private LocalDate correctedDate;

    /** The day the claim is due by: fixed when it is made, from its date and the terms of its
     *  person's grade in force on that date; later changes to the terms or its date leave it. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The day the claim is deferred until (see {@link #isDeferredOn}); null when never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs the claim has; raised by one at a time (see {@link #addProof}). */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number of the claim this claim was split off (see {@link #splitOff}); null for a claim
     *  that was not split off one. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The user who has the claim's editor open, locking it for every other user; null when no one
     *  has. */
    @Column(name = "edit_locked_by")
    private String editLockedBy;

    /** Whether the claim was added while the period its date falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** Where the claim is listed: newest first by this. A new claim takes the next from the
     *  database, and a moved claim takes the next again (see {@link #moveTo}). */
    @Generated
    @Column(name = "listed", insertable = false)
    private Long listed;

    /** The claim's status log, oldest first: a line for each status it has had (see {@link #logStatus}). */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @JoinColumn(name = "claim_id", nullable = false, updatable = false)
    @OrderBy("id")
    private List<ClaimLog> log = new ArrayList<>();

    protected Claim() {
    }

    /** The claim as a revision of it has it, detached: for working out figures only, never saved. */
    static Claim revised(ClaimRevision revision) {
        Claim claim = new Claim(revision.getSheetId(), revision.getPersonId(), revision.getAmount(),
                revision.getDate(), "", null, revision.getCorrectedDate(), revision.getDueBy());
        claim.id = revision.getClaimId();
        claim.status = revision.getStatus();
        claim.settledDue = revision.getSettledDue();
        claim.bind(revision.isStated(), revision.getStatedDue(), revision.isStatedNa());
        claim.deferredUntil = revision.getDeferredUntil();
        return claim;
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate correctedDate, LocalDate dueBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
        this.correctedDate = correctedDate;
        this.dueBy = dueBy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public Long getListed() {
        return listed;
    }

    /** Move the claim to another person, listed at the place given (after every claim listed so far).
     *  It keeps its number, date and status, but no figure a statement bound it to: it is live
     *  again until its new person's next statement. */
    public void moveTo(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
        bind(false, null);
    }

    /** Split the amount off this open claim: it keeps the rest of its amount but no figure a
     *  statement bound it to, and the new open claim returned has the amount, the same date and
     *  note, the number and opener given, the due-by given, and this claim's number as split-from. */
    public Claim splitOff(BigDecimal part, String number, String openedBy, LocalDate dueBy) {
        this.amount = amount.subtract(part);
        bind(false, null);
        Claim split = new Claim(sheetId, personId, part, date, note, null, null, dueBy);
        split.status = ClaimStatus.OPEN;
        split.number = number;
        split.openedBy = openedBy;
        split.splitFrom = this.number;
        return split;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void markLateEntry() {
        this.lateEntry = true;
    }

    public String getEditLockedBy() {
        return editLockedBy;
    }

    public void setEditLockedBy(String editLockedBy) {
        this.editLockedBy = editLockedBy;
    }

    /** Whether another user than this one has the claim's editor open. */
    public boolean editLockedFor(String user) {
        return editLockedBy != null && !editLockedBy.equals(user);
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getCorrectedDate() {
        return correctedDate;
    }

    public void setCorrectedDate(LocalDate correctedDate) {
        this.correctedDate = correctedDate;
    }

    /** The date the claim's figures round by: the date of the claim a correction corrects, or else
     *  its own. */
    public LocalDate roundsBy() {
        return correctedDate != null ? correctedDate : date;
    }

    /** Whether the claim is a correction: its amount is below 0.00. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void deferUntil(LocalDate until) {
        this.deferredUntil = until;
    }

    public int getProofs() {
        return proofs;
    }

    /** Raise the claim's proofs count by one. */
    public void addProof() {
        this.proofs++;
    }

    /** Whether the claim is deferred on the day: it is open and the day is before the one it is
     *  deferred until. A deferred claim counts in no total, is not overdue, cannot be settled and a
     *  statement leaves it unbound; from that day on it is an open claim like any other. */
    public boolean isDeferredOn(LocalDate day) {
        return status == ClaimStatus.OPEN && deferredUntil != null && day.isBefore(deferredUntil);
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    public boolean isStatedNa() {
        return statedNa;
    }

    /** Bind the claim to a due (null: none), or unbind it. */
    public void bind(boolean stated, BigDecimal statedDue) {
        bind(stated, statedDue, false);
    }

    /** Bind the claim to a due (null: none, or n/a when {@code na}), or unbind it. */
    public void bind(boolean stated, BigDecimal statedDue, boolean na) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
        this.statedNa = stated && statedDue == null && na;
    }

    /** The status the claim had at the end of the day, as its status log records it: that of the
     *  last line logged on or before the day; null when it was not yet made then. A claim with no
     *  log has its status now. */
    public ClaimStatus statusOn(LocalDate day) {
        if (log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLog line : log) {
            if (!line.getOn().isAfter(day)) {
                then = line.getStatus();
            }
        }
        return then;
    }

    public List<ClaimLog> getLog() {
        return List.copyOf(log);
    }

    /** Log the status the claim has now: changed by the user on the day (the sheet's today), with
     *  its due as computed at that moment (null when it has none). */
    public void logStatus(String user, LocalDate on, BigDecimal due) {
        log.add(new ClaimLog(sheetId, status, user, on, due));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;

/** The due figures of claims, and the due-totals of people, at the rates on a sheet: as they are
 *  now, or on any other {@link Basis} (such as the sheet as it stood at the end of an earlier day). */
@Service
public class Dues {

    /** What a sheet's figures are worked out from: its today, its dated settings and its rates. */
    public interface Basis {

        /** The day that stands in for the sheet's today. */
        LocalDate today();

        /** The floor in force on a day. */
        BigDecimal floor(LocalDate day);

        /** The late percent in force on a day. */
        BigDecimal latePct(LocalDate day);

        /** The cap in force on the basis's today; null when there is none. */
        BigDecimal cap();

        /** The policy date in force: the one set, or else the basis's today. */
        LocalDate policyDateInForce();

        /** The rates of a grade, the latest from-date first and the one with none last. */
        List<Rate> rates(String grade);
    }

    private final RateRepository rates;
    private final SheetService sheets;

    public Dues(RateRepository rates, SheetService sheets) {
        this.rates = rates;
        this.sheets = sheets;
    }

    /** The sheet as it is now: its today, its settings and its rates. */
    public Basis now(String sheetId) {
        return new Basis() {
            @Override
            public LocalDate today() {
                return sheets.today(sheetId);
            }

            @Override
            public BigDecimal floor(LocalDate day) {
                return sheets.floor(sheetId, day);
            }

            @Override
            public BigDecimal latePct(LocalDate day) {
                return sheets.latePct(sheetId, day);
            }

            @Override
            public BigDecimal cap() {
                return sheets.cap(sheetId);
            }

            @Override
            public LocalDate policyDateInForce() {
                return sheets.policyDateInForce(sheetId);
            }

            @Override
            public List<Rate> rates(String grade) {
                return rates.findLatestFirst(sheetId, grade);
            }
        };
    }

    /** The due figure a claim shows and totals: the one fixed when it was settled, or else its
     *  {@link #bindable} rate figure with the late charge on that figure on top while it is overdue,
     *  at least the sheet's floor in force on the claim's date (a correction has neither); null when
     *  there is none. */
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        return figure(now(sheetId), person, claim);
    }

    /** The due figure a claim shows and totals on a basis (see {@link #figure(String, Person, Claim)}). */
    public BigDecimal figure(Basis basis, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return floored(basis, claim, bindable(basis, person, claim), claim.getStatus().isOpen());
    }

    /** The figure a claim would have today as an open claim bound by no statement: its rate figure
     *  with the late charge on top while it is overdue, at least the floor in force on its date; null
     *  when there is none. */
    public BigDecimal openFigure(String sheetId, Person person, Claim claim) {
        Basis basis = now(sheetId);
        return floored(basis, claim, due(basis, person, claim), true);
    }

    /** A rate figure with its late charge (taken as open or not) on top, then at least the sheet's
     *  floor in force on the claim's date (a correction has no floor); null when the figure is. */
    private BigDecimal floored(Basis basis, Claim claim, BigDecimal figure, boolean open) {
        if (figure == null) {
            return null;
        }
        BigDecimal charged = figure.add(lateCharge(basis, claim, figure, open));
        return claim.isCorrection() ? charged : charged.max(basis.floor(claim.getDate()));
    }

    /** The rate figure a statement binds a claim to: the one its person's last statement bound it to,
     *  or else its live rate figure (a pending claim is not bound by a statement while it is pending);
     *  never the late charge, which keeps following the sheet's today, nor the floor, which is applied
     *  last. Null when there is none, or when the statement bound it to n/a. */
    public BigDecimal bindable(String sheetId, Person person, Claim claim) {
        return bindable(now(sheetId), person, claim);
    }

    /** The rate figure a statement binds a claim to on a basis (see {@link #bindable(String, Person, Claim)}). */
    public BigDecimal bindable(Basis basis, Person person, Claim claim) {
        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
            return claim.getStatedDue();
        }
        return due(basis, person, claim);
    }

    /** Whether a statement binds a claim to n/a: its person's last statement bound it to n/a, or
     *  else it has no bound figure and no live due: no rate applies to it on its date (for the
     *  person's grade on that date), none ever having been set or the one that would having ended. */
    public boolean bindsNa(String sheetId, Person person, Claim claim) {
        return bindsNa(now(sheetId), person, claim);
    }

    /** Whether a statement binds a claim to n/a on a basis (see {@link #bindsNa(String, Person, Claim)}). */
    public boolean bindsNa(Basis basis, Person person, Claim claim) {
        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
            return claim.isStatedNa();
        }
        return due(basis, person, claim) == null;
    }

    /** Whether a claim is bound by its person's last statement now (a pending claim is not). */
    private static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** The late charge on a claim taken as open (or pending) or not, overdue on the sheet's today (its due-by, fixed when it was
     *  made, before today; a correction has none): for each full 30 days it is overdue, the late percent in force on
     *  that boundary (its due-by plus 30, 60, 90 ... days) of its figure, rounded to two decimals by the claim's
     *  {@link #rounding}, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue. */
    private BigDecimal lateCharge(Basis basis, Claim claim, BigDecimal figure, boolean open) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        LocalDate today = basis.today();
        if (!open || claim.isCorrection() || claim.isDeferredOn(today)) {
            return none;
        }
        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), today) / 30;
        if (periods <= 0) {
            return none;
        }
        RoundingMode rounding = rounding(basis, claim);
        BigDecimal charge = none;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = basis.latePct(claim.getDueBy().plusDays(30 * n));
            if (pct.signum() != 0) {
                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
            }
        }
        return charge;
    }

    /** Whether a claim of the person counts in the live totals on the sheet's today: it counts, it is
     *  not deferred on that day, and it is not an open (or pending) claim, unbound by a statement,
     *  dated within one of the person's holds or of a person retired on that day. */
    public static boolean countsLive(Person person, Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
    }

    /** Whether a claim of the person counts in a period's totals: by the status it had at the end of
     *  the period's last day (see Claim#statusOn) it counts, and the live rules do not leave it out:
     *  it is not deferred on the sheet's today, and it is not a claim open (or pending) now,
     *  unbound by a statement, dated within one of the person's holds or of a person retired on the
     *  sheet's today. */
    public static boolean countsAsOf(Person person, Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus then = claim.statusOn(end);
        return then != null && then.counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
    }

    /** Whether the live rules leave a claim of the person out: it is open (or pending) now, unbound
     *  by a statement, and dated within one of the person's holds or the person is retired on the
     *  sheet's today. */
    private static boolean leftOut(Person person, Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && !claim.isStated()
                && (person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
    }

    /** The claims of a person that count in the live totals on the sheet's today. */
    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
    }

    /** A person's due-total: the sum of the figures of their claims that count, at most the sheet's
     *  cap in force on its today; null (n/a) when their grade on the sheet's today has no rate on it and no counting claim
     *  has a figure (one fixed, or a live due at the grade in force on its date). */
    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
        return dueTotal(now(sheetId), person, theirs);
    }

    /** A person's due-total on a basis (see {@link #dueTotal(String, Person, List)}). */
    public BigDecimal dueTotal(Basis basis, Person person, List<Claim> theirs) {
        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
                .map(c -> figure(basis, person, c)).filter(d -> d != null).toList();
        LocalDate today = basis.today();
        boolean rated = RateRepository.inForce(basis.rates(person.gradeOn(today)), today).isPresent();
        if (!rated && figures.isEmpty()) {
            return null;
        }
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        BigDecimal cap = basis.cap();
        return cap == null ? sum : sum.min(cap);
    }

    /** A claim's live due at the rate, in force on the claim's date, for the person's grade in force
     *  on that date: amount
     *  times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
     *  applied later, see {@link #floored}); null when no rate applies on that date. */
    private BigDecimal due(Basis basis, Person person, Claim claim) {
        RoundingMode rounding = rounding(basis, claim);
        return RateRepository.inForce(basis.rates(person.gradeOn(claim.getDate())), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .orElse(null);
    }

    /** How a claim's live figures round: half up when the date it rounds by (a correction's is that of
     *  the claim it corrects) is before the sheet's policy date, else half to even. */
    private RoundingMode rounding(Basis basis, Claim claim) {
        return claim.roundsBy().isBefore(basis.policyDateInForce()) ? RoundingMode.HALF_UP
                : RoundingMode.HALF_EVEN;
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.watch.WatchService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The claims people make on a sheet. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final SheetService sheets;
    private final Rollup rollup;
    private final PeriodRepository periods;
    private final RoleService roles;
    private final WatchService watches;
    private final Audit audit;

    /** How many days after its settlement a steward may still void a settled claim. */
    static final int VOID_SETTLED_DAYS = 7;

    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
            Rollup rollup, PeriodRepository periods, RoleService roles, WatchService watches,
            Audit audit) {
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
        this.roles = roles;
        this.watches = watches;
        this.audit = audit;
    }

    /** The claims on the sheet, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    /** Add a claim for a person; a date left out takes the sheet's entry date, or its today when none
     *  is set. Refused when the date falls
     *  inside a closed period, or after the person's retirement day, and when a correction (a negative
     *  amount) does not name a settled claim of the person. */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        return add(sheetId, user, personId, amount, date, note, null);
    }

    /** Add a claim for a person, naming the number of the claim it corrects (only a correction keeps it). */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        LocalDate on = date != null ? date : sheets.entryDay(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person(sheetId, personId), on);
        Claim corrected = corrected(sheetId, personId, amount, corrects);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, personId);
            Claim draft = new Claim(sheetId, personId, amount, on, note,
                    corrected == null ? null : corrected.getNumber(), corrected == null ? null : corrected.getDate(),
                    dueBy(sheetId, person, on));
            boolean late = periods.softClosedOn(sheetId, on);
            if (late) {
                draft.markLateEntry();
            }
            logStatus(sheetId, user, person, draft);
            Claim claim = claims.saveAndFlush(draft);
            audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim));
            if (late) {
                audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, claim));
            }
            return claim;
        });
    }

    /** Change a draft claim's amount, date and note; a date left out takes the sheet's today. Refused
     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
     *  when the claim's date, or the new one, falls inside a closed period, and when the new one is
     *  after the person's retirement day. */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = lock(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited, nor one another user is editing");
        }
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        refuseRetired(person(sheetId, claim.getPersonId()), on);
        Claim corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
        return rollup.tracking(sheetId, user, () -> {
            claim.setAmount(amount);
            claim.setCorrects(corrected == null ? null : corrected.getNumber());
            claim.setCorrectedDate(corrected == null ? null : corrected.getDate());
            claim.setDate(on);
            claim.setNote(note);
            claim.setEditLockedBy(null);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
            return saved;
        });
    }

    /** Open a claim's editor for the user, locking the claim for every other user until it is saved
     *  or cancelled or the sheet's today changes; an editor the user had open on another claim of the
     *  same person is closed. Refused when the claim is not a draft or another user has its editor
     *  open (409), and when it is dated inside a closed period (423). Records nothing. */
    @Transactional
    public Claim openEditor(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited, nor one another user is editing");
        }
        refuseClosed(sheetId, claim.getDate());
        claims.releaseOtherEditLocks(sheetId, claim.getPersonId(), user, claim.getId());
        claim.setEditLockedBy(user);
        return claims.saveAndFlush(claim);
    }

    /** Close the claim's editor the user has open (cancelled), unlocking the claim; a claim whose
     *  editor the user does not have open is left as it is. Records nothing. */
    @Transactional
    public Claim closeEditor(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        if (!user.equals(claim.getEditLockedBy())) {
            return claim;
        }
        claim.setEditLockedBy(null);
        return claims.saveAndFlush(claim);
    }

    /** Move a claim to a new status; a change its current status does not allow is refused, and so
     *  is settling a claim by the user who opened it, and any change to a claim dated inside a closed
     *  period, and any change the permission matrix does not allow the user's role. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
     *  a steward's approval instead; but settling a claim that needs a proof and has none is refused
     *  before the clerk limit is considered. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            return voidSettled(sheetId, user, claim);
        }
        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + to);
        }
        String action = switch (to) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            default -> "void";
        };
        if (!roles.may(sheetId, user, action)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
        }
        if (to == ClaimStatus.OPEN) {
            refuseUnnoted(sheetId, claim);
        }
        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it");
        }
        if (to == ClaimStatus.SETTLED) {
            refuseUnproved(sheetId, claim);
        }
        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
                ? ClaimStatus.PENDING : to;
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            if (becomes == ClaimStatus.SETTLED) {
                // Settling fixes the due at what it is now, while the claim is still open (the figure a
                // statement bound it to, if any, and its late charge); later changes to rates, the
                // late percent and the sheet's today do not alter it.
                claim.setSettledDue(dues.figure(sheetId, person, claim));
            }
            // A void claim keeps the number it had (never reused).
            claim.setStatus(becomes);
            if (becomes == ClaimStatus.OPEN) {
                claim.setNumber(nextNumber(sheetId, claim.getDate()));
                claim.setOpenedBy(user);
            }
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            String event = switch (becomes) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
            };
            String line = record(event, sheetId, user, person, saved);
            if (becomes == ClaimStatus.SETTLED) {
                line += " due=" + dueText(saved.getSettledDue());
            }
            audit.recordOnCommit(line);
            if (becomes == ClaimStatus.SETTLED) {
                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
            }
            return saved;
        });
    }

    /** Void a settled claim: only a steward may, within {@value #VOID_SETTLED_DAYS} days of its
     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
    private Claim voidSettled(String sheetId, String user, Claim claim) {
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
        }
        LocalDate today = sheets.today(sheetId);
        LocalDate settled = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
                .map(ClaimLog::getOn).findFirst().orElse(null);
        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            BigDecimal reversed = dues.figure(sheetId, person, claim);
            claim.setStatus(ClaimStatus.VOID);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed));
            return saved;
        });
    }

    /** Defer an open claim until a day after the sheet's today: until the sheet's today reaches it,
     *  the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
     *  unbound. Refused when the claim's period is closed, the claim is not open, or the day is not
     *  after the sheet's today. */
    @Transactional
    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deferred");
        }
        if (!until.isAfter(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim can only be deferred to a date after the sheet's today");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.deferUntil(until);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved) + " until=" + until);
            return saved;
        });
    }

    /** Raise a claim's proofs count by one. Refused when the claim is settled or void, or its period
     *  is closed. It changes no figure. */
    @Transactional
    public Claim addProof(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be given a proof");
        }
        Person person = person(sheetId, claim.getPersonId());
        claim.addProof();
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved) + " proofs=" + saved.getProofs());
        return saved;
    }

    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
     *  the one who opened it, the claim's period is open, and it has a proof if it needs one. */
    @Transactional
    public Claim approve(String sheetId, String user, long claimId) {
        Claim claim = lockPending(sheetId, user, claimId);
        if (user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot approve it");
        }
        refuseUnproved(sheetId, claim);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setSettledDue(dues.figure(sheetId, person, claim));
            claim.setStatus(ClaimStatus.SETTLED);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
                    + " due=" + dueText(saved.getSettledDue()));
            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
            return saved;
        });
    }

    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
     *  claim is settled, the user is a steward, and the claim's period is open. */
    @Transactional
    public Claim resettle(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            BigDecimal old = dues.figure(sheetId, person, claim);
            BigDecimal now = dues.openFigure(sheetId, person, claim);
            claim.setSettledDue(now);
            claim.logStatus(user, sheets.today(sheetId), now);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
                    + " old=" + dueText(old) + " new=" + dueText(now));
            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
            return saved;
        });
    }

    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
     *  statement if that statement included it. Refused unless the claim is pending, the user is a
     *  steward, and the claim's period is open. */
    @Transactional
    public Claim reject(String sheetId, String user, long claimId, String reason) {
        Claim claim = lockPending(sheetId, user, claimId);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setStatus(ClaimStatus.OPEN);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
            return saved;
        });
    }

    /** Move a draft, open or pending claim to another person on the sheet. It keeps its number, date
     *  and status, loses any figure a statement bound it to, and is listed as its new person's newest
     *  claim. Refused unless the permission matrix allows the user's role to reassign, and when the claim is settled or void, the person
     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
     *  new person's retirement day. */
    @Transactional
    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
        Claim claim = lock(sheetId, claimId);
        if (!roles.may(sheetId, user, "reassign")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
        }
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be reassigned");
        }
        if (claim.getPersonId() == toPersonId) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
        }
        refuseClosed(sheetId, claim.getDate());
        Person from = person(sheetId, claim.getPersonId());
        Person to = person(sheetId, toPersonId);
        refuseRetired(to, claim.getDate());
        return rollup.tracking(sheetId, user, () -> {
            claim.moveTo(to.getId(), claims.nextListed());
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
                    + " from=" + from.getName() + " to=" + to.getName());
            return saved;
        });
    }

    /** Re-date an open or pending claim: it keeps the due-by it was fixed with and any figure a
     *  statement bound it to, and its period follows the new date; under period numbering, a claim
     *  whose period changes takes the next number of its new period (its old one is never reused).
     *  Refused unless the user is a steward, and when the claim is not open or pending, its period or
     *  the new date's is closed, or the new date is after the person's retirement day. */
    @Transactional
    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
        Claim claim = lock(sheetId, claimId);
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim");
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be re-dated");
        }
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, date);
        refuseRetired(person(sheetId, claim.getPersonId()), date);
        LocalDate old = claim.getDate();
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            boolean periodChanges = !periods.findOn(sheetId, old).map(p -> p.getId())
                    .equals(periods.findOn(sheetId, date).map(p -> p.getId()));
            claim.setDate(date);
            if (periodChanges && sheets.periodNumbering(sheetId)) {
                claim.setNumber(nextNumber(sheetId, date));
            }
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
                    + " old=" + old + " new=" + date);
            return saved;
        });
    }

    /** What a split leaves:the original claim, with the rest of its amount, and the new open claim
     *  split off it. */
    public record Split(Claim original, Claim split) {
    }

    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
     *  the same date and note, the next number, opened by the user and due by the terms in force on
     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
     *  allow the user's role to open a claim. */
    @Transactional
    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
        }
        if (!roles.may(sheetId, user, "open")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
        }
        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "The amount split off must be above 0.00 and below the claim's amount");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            LocalDate on = claim.getDate();
            Claim draft = claim.splitOff(part, nextNumber(sheetId, on), user,
                    dueBy(sheetId, person, on));
            logStatus(sheetId, user, person, draft);
            Claim original = claims.saveAndFlush(claim);
            Claim split = claims.saveAndFlush(draft);
            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
            return new Split(original, split);
        });
    }

    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
     *  user is not a steward, or its period is closed. */
    private Claim lockPending(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "Only a PENDING claim can be approved or rejected");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward can approve or reject a claim");
        }
        return claim;
    }

    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
     *  computed at this moment. */
    private void logStatus(String sheetId, String user, Person person, Claim claim) {
        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
    }

    private Claim lock(String sheetId, long claimId) {
        return claims.lockByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
    }

    private static String dueText(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }

    /** The number for a claim of the date opened now: under period numbering, the next in its period
     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
    private String nextNumber(String sheetId, LocalDate date) {
        if (!sheets.periodNumbering(sheetId)) {
            return String.valueOf(sheets.nextClaimNumber(sheetId));
        }
        return periods.findOn(sheetId, date)
                .map(p -> {
                    periods.advanceClaimNumber(p.getId());
                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
                })
                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
    }

    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
     *  or else it is refused. */
    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            return null;
        }
        return (corrects == null ? Optional.<Claim>empty()
                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "A negative amount must correct a settled claim of the same person"));
    }

    /** Refuse a change to a claim dated on the day when the day falls inside a closed period. */
    private void refuseClosed(String sheetId, LocalDate day) {
        if (periods.closedOn(sheetId, day)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
        }
    }

    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
     *  no due (n/a) is within any limit, and a steward settles anything. */
    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
        BigDecimal limit = sheets.clerkLimit(sheetId);
        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            return false;
        }
        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
        return due != null && due.compareTo(limit) > 0;
    }

    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof
     *  threshold in force on the claim's date; a claim with no due (n/a) and a sheet with no threshold
     *  need none. */
    private void refuseUnproved(String sheetId, Claim claim) {
        BigDecimal threshold = sheets.proofThreshold(sheetId, claim.getDate());
        if (threshold == null || claim.getProofs() > 0) {
            return;
        }
        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
                    "A claim whose due is above the proof threshold needs a proof first");
        }
    }

    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
    private void refuseUnnoted(String sheetId, Claim claim) {
