153	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
154	     *  is settling a claim by the user who opened it, and any change to a claim dated inside a closed
155	     *  period, and any change the permission matrix does not allow the user's role. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
156	     *  a steward's approval instead; but settling a claim that needs a proof and has none is refused
157	     *  before the clerk limit is considered. */
158	    @Transactional
159	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
160	        Claim claim = lock(sheetId, claimId);
161	        refuseClosed(sheetId, claim.getDate());
162	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
163	            return voidSettled(sheetId, user, claim);
164	        }
165	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
166	            throw new ResponseStatusException(HttpStatus.CONFLICT,
167	                    "A " + claim.getStatus() + " claim cannot become " + to);
168	        }
169	        String action = switch (to) {
170	            case OPEN -> "open";
171	            case SETTLED -> "settle";
172	            default -> "void";
173	        };
174	        if (!roles.may(sheetId, user, action)) {
175	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
176	        }
177	        if (to == ClaimStatus.OPEN) {
178	            refuseUnnoted(sheetId, claim);
179	        }
180	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
181	            throw new ResponseStatusException(HttpStatus.CONFLICT,
182	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
183	        }
184	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
185	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
186	                    "The user who opened a claim cannot settle it");
187	        }
188	        if (to == ClaimStatus.SETTLED) {
189	            refuseUnproved(sheetId, claim);
190	        }
191	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
192	                ? ClaimStatus.PENDING : to;
193	        return rollup.tracking(sheetId, user, () -> {
194	            Person person = person(sheetId, claim.getPersonId());
195	            if (becomes == ClaimStatus.SETTLED) {
196	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
197	                // statement bound it to, if any, and its late charge); later changes to rates, the
198	                // late percent and the sheet's today do not alter it.
199	                claim.setSettledDue(dues.figure(sheetId, person, claim));
200	            }
201	            // A void claim keeps the number it had (never reused).
202	            claim.setStatus(becomes);
203	            if (becomes == ClaimStatus.OPEN) {
204	                claim.setNumber(nextNumber(sheetId, claim.getDate()));
205	                claim.setOpenedBy(user);
206	            }
207	            logStatus(sheetId, user, person, claim);
208	            Claim saved = claims.saveAndFlush(claim);
209	            String event = switch (becomes) {
210	                case OPEN -> "CLAIM_OPENED";
211	                case PENDING -> "CLAIM_PENDING";
212	                case SETTLED -> "CLAIM_SETTLED";
213	                case VOID -> "CLAIM_VOIDED";
214	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
215	            };
216	            String line = record(event, sheetId, user, person, saved);
217	            if (becomes == ClaimStatus.SETTLED) {
218	                line += " due=" + dueText(saved.getSettledDue());
219	            }
220	            audit.recordOnCommit(line);
221	            if (becomes == ClaimStatus.SETTLED) {
222	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
223	            }
224	            return saved;
225	        });
226	    }
