228	    /** Void a settled claim: only a steward may, within {@value #VOID_SETTLED_DAYS} days of its
229	     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
230	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
231	    private Claim voidSettled(String sheetId, String user, Claim claim) {
232	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
233	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
234	        }
235	        LocalDate today = sheets.today(sheetId);
236	        LocalDate settled = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
237	                .map(ClaimLog::getOn).findFirst().orElse(null);
238	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
239	            throw new ResponseStatusException(HttpStatus.CONFLICT,
240	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
241	        }
242	        return rollup.tracking(sheetId, user, () -> {
243	            Person person = person(sheetId, claim.getPersonId());
244	            BigDecimal reversed = dues.figure(sheetId, person, claim);
245	            claim.setStatus(ClaimStatus.VOID);
246	            logStatus(sheetId, user, person, claim);
247	            Claim saved = claims.saveAndFlush(claim);
248	            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed));
249	            return saved;
250	        });
251	    }
