393	    /** Re-date an open or pending claim: it keeps the due-by it was fixed with and any figure a
394	     *  statement bound it to, and its period follows the new date; under period numbering, a claim
395	     *  whose period changes takes the next number of its new period (its old one is never reused).
396	     *  Refused unless the user is a steward, and when the claim is not open or pending, its period or
397	     *  the new date's is closed, or the new date is after the person's retirement day. */
398	    @Transactional
399	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
400	        Claim claim = lock(sheetId, claimId);
401	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
402	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim");
403	        }
404	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
405	            throw new ResponseStatusException(HttpStatus.CONFLICT,
406	                    "A " + claim.getStatus() + " claim cannot be re-dated");
407	        }
408	        refuseClosed(sheetId, claim.getDate());
409	        refuseClosed(sheetId, date);
410	        refuseRetired(person(sheetId, claim.getPersonId()), date);
411	        LocalDate old = claim.getDate();
412	        return rollup.tracking(sheetId, user, () -> {
413	            Person person = person(sheetId, claim.getPersonId());
414	            boolean periodChanges = !periods.findOn(sheetId, old).map(p -> p.getId())
415	                    .equals(periods.findOn(sheetId, date).map(p -> p.getId()));
416	            claim.setDate(date);
417	            if (periodChanges && sheets.periodNumbering(sheetId)) {
418	                claim.setNumber(nextNumber(sheetId, date));
419	            }
420	            Claim saved = claims.saveAndFlush(claim);
421	            audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
422	                    + " old=" + old + " new=" + date);
423	            return saved;
424	        });
425	    }
