432	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
433	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
434	     *  the same date and note, the next number, opened by the user and due by the terms in force on
435	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
436	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
437	     *  allow the user's role to open a claim. */
438	    @Transactional
439	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
440	        Claim claim = lock(sheetId, claimId);
441	        refuseClosed(sheetId, claim.getDate());
442	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
443	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
444	        }
445	        if (!roles.may(sheetId, user, "open")) {
446	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
447	        }
448	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
449	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
450	                    "The amount split off must be above 0.00 and below the claim's amount");
451	        }
452	        return rollup.tracking(sheetId, user, () -> {
453	            Person person = person(sheetId, claim.getPersonId());
454	            LocalDate on = claim.getDate();
455	            Claim draft = claim.splitOff(part, nextNumber(sheetId, on), user,
456	                    dueBy(sheetId, person, on));
457	            logStatus(sheetId, user, person, draft);
458	            Claim original = claims.saveAndFlush(claim);
459	            Claim split = claims.saveAndFlush(draft);
460	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
461	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
462	            return new Split(original, split);
463	        });
464	    }
