531	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
532	     *  no due (n/a) is within any limit, and a steward settles anything. */
533	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
534	        BigDecimal limit = sheets.clerkLimit(sheetId);
535	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
536	            return false;
537	        }
538	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
539	        return due != null && due.compareTo(limit) > 0;
540	    }
