542	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof
543	     *  threshold in force on the claim's date; a claim with no due (n/a) and a sheet with no threshold
544	     *  need none. */
545	    private void refuseUnproved(String sheetId, Claim claim) {
546	        BigDecimal threshold = sheets.proofThreshold(sheetId, claim.getDate());
547	        if (threshold == null || claim.getProofs() > 0) {
548	            return;
549	        }
550	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
551	        if (due != null && due.compareTo(threshold) > 0) {
552	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
553	                    "A claim whose due is above the proof threshold needs a proof first");
554	        }
555	    }
556	
557	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
558	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
559	    private void refuseUnnoted(String sheetId, Claim claim) {
560	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
561	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
562	            return;
563	        }
564	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
565	        if (due != null && due.compareTo(threshold) > 0) {
566	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
567	                    "A claim whose due is above the note threshold needs a note before it is opened");
568	        }
569	    }
570	
571	    /** Refuse a claim of the person dated after the day they are retired from. */
572	    private static void refuseRetired(Person person, LocalDate day) {
573	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
574	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
575	                    "A claim cannot be dated after the person's retirement");
576	        }
577	    }
578	
579	    /** The day a claim of the person dated on the day is due by: its date plus the first of the
580	     *  person's own terms, their grade's and the sheet's, each as in force on the day. */
581	    private LocalDate dueBy(String sheetId, Person person, LocalDate on) {
582	        Integer own = person.getTerms();
583	        return on.plusDays(own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on));
584	    }
585	
586	    private Person person(String sheetId, long personId) {
587	        return people.findByIdAndSheetId(personId, sheetId)
588	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
589	    }
590	
591	    /** An audit record about a claim; one that has a number carries it at the end. */
592	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
593	        String number = claim.getNumber();
594	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
595	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
596	                + (number != null ? " number=" + number : "");
597	    }
598	}
